public void defaultField(FieldId _fieldId)
{
    super(_fieldId);

    switch (_fieldId)
    {
        case fieldNum(GUPSalesAutomaticSalesDocumentHeaderChargeEntity, FixedChargeAmount):
            this.defaultChargeCategoryValue(MarkupCategory::Fixed);
            break;
        case fieldNum(GUPSalesAutomaticSalesDocumentHeaderChargeEntity, ChargePercentage):
            this.defaultChargeCategoryValue(MarkupCategory::Percent);
            break;
        case fieldNum(GUPSalesAutomaticSalesDocumentHeaderChargeEntity, Value):
            this.defaultValue();
            break;
    }

}

private void defaultChargeCategoryValue(MarkupCategory _chargeCategory)
{
    if (this.isFieldSet(fieldNum(GUPSalesAutomaticSalesDocumentHeaderChargeEntity, ChargeCategory)))
    {
        if (this.ChargeCategory != _chargeCategory)
        {
            this.(this.getChargeCategoryValueFieldId(_chargeCategory)) = 0.0;
        }
    }
}

private void defaultValue()
{
    FieldId chargeCategoryValueFieldId = this.getChargeCategoryValueFieldId(this.ChargeCategory);

    if (this.isFieldSet(fieldNum(GUPSalesAutomaticSalesDocumentHeaderChargeEntity, ChargeCategory))  ||
        this.isFieldSet(chargeCategoryValueFieldId))
    {
        this.Value = this.(chargeCategoryValueFieldId);
    }
}

public container getDefaultingDependencies()
{
    return [
            [fieldNum(GUPSalesAutomaticSalesDocumentHeaderChargeEntity, FixedChargeAmount), this.fixedChargeAmountDefaultingDependencies()],
            [fieldNum(GUPSalesAutomaticSalesDocumentHeaderChargeEntity, ChargePercentage), this.chargePercentageDefaultingDependencies()],
            [fieldNum(GUPSalesAutomaticSalesDocumentHeaderChargeEntity, Value), this.valueDefaultingDependencies()]
    ];
}

private container fixedChargeAmountDefaultingDependencies()
{
    return [fieldNum(GUPSalesAutomaticSalesDocumentHeaderChargeEntity, ChargeCategory)];
}

private container chargePercentageDefaultingDependencies()
{
    return [fieldNum(GUPSalesAutomaticSalesDocumentHeaderChargeEntity, ChargeCategory)];
}

private container valueDefaultingDependencies()
{
    return [fieldNum(GUPSalesAutomaticSalesDocumentHeaderChargeEntity, ChargeCategory),
            fieldNum(GUPSalesAutomaticSalesDocumentHeaderChargeEntity, FixedChargeAmount),
            fieldNum(GUPSalesAutomaticSalesDocumentHeaderChargeEntity, ChargePercentage)];
}

public TableExtension getExtension()
{
    return SysTableExtension::construct();
}

private FieldId getChargeCategoryValueFieldId(MarkupCategory _chargeCategory)
{
    FieldId chargeCategoryValueFieldId;

    switch (_chargeCategory)
    {
        case MarkupCategory::Fixed:
            chargeCategoryValueFieldId = fieldNum(GUPSalesAutomaticSalesDocumentHeaderChargeEntity, FixedChargeAmount);
            break;

        case MarkupCategory::Percent:
            chargeCategoryValueFieldId = fieldNum(GUPSalesAutomaticSalesDocumentHeaderChargeEntity, ChargePercentage);
            break;

        default:
            throw error(strFmt("@SCM:ChargeCategoryValueCannotBeSpecified", _chargeCategory, fieldPName(GUPSalesAutomaticSalesDocumentHeaderChargeEntity, ChargeCategory)));
    }

    return chargeCategoryValueFieldId;
}

public boolean validateField(FieldId _fieldIdToCheck)
{
    boolean ret;

    ret = super(_fieldIdToCheck);

    switch (_fieldIdToCheck)
    {
        case fieldNum(GUPSalesAutomaticSalesDocumentHeaderChargeEntity, FixedChargeAmount):
            ret = this.checkChargeCategoryValue(MarkupCategory::Fixed) && ret;
            break;

        case fieldNum(GUPSalesAutomaticSalesDocumentHeaderChargeEntity, ChargePercentage):
            ret = this.checkChargeCategoryValue(MarkupCategory::Percent) && ret;
            break;
    }

    return ret;
}

private boolean checkChargeCategoryValue(MarkupCategory _chargeCategory)
{
    boolean ok = true;

    if (this.chargeCategory != _chargeCategory)
    {
        if (this.(this.getChargeCategoryValueFieldId(_chargeCategory)) != 0.0)
        {
            ok = this.chargeCategoryValueCheckFailed(_chargeCategory);
        }
    }

    return ok;
}

private boolean chargeCategoryValueCheckFailed(MarkupCategory _correctChargeCategory)
{
    FieldId correctChargeCategoryValueFieldId   = this.getChargeCategoryValueFieldId(_correctChargeCategory);
    FieldId incorrectChargeCategoryValueFieldId = this.getChargeCategoryValueFieldId(this.chargeCategory);

    return checkFailed(strFmt("@SCM:ChargeCategoryAndChargeValueMismatchErrorMessage",
                               fieldId2pname(tablenum(GUPSalesAutomaticSalesDocumentHeaderChargeEntity), correctChargeCategoryValueFieldId),
                               fieldPName(GUPSalesAutomaticSalesDocumentHeaderChargeEntity, ChargeCategory),
                               _correctChargeCategory,
                               fieldId2pname(tablenum(GUPSalesAutomaticSalesDocumentHeaderChargeEntity), incorrectChargeCategoryValueFieldId)));
}

public boolean insertEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    if (_dataSourceCtx.name() == dataEntityDataSourceStr(GUPSalesAutomaticSalesDocumentHeaderChargeEntity, MarkupAutoTable))
    {
        MarkupAutoTable markupAutoTable = _dataSourceCtx.getBuffer() as markupAutoTable;

        markupAutoTable.IsGupMarkupAuto = NoYes::Yes;
        markupAutoTable.PriceComponentType = GUPPriceComponent::AutoCharges;
        markupAutoTable.AccountCode = TableGroupAll::All;
        markupAutoTable.ItemCode = TableGroupAll::All;

        this.updatePriceComponentCodeAndGroupCombination(
            markupAutoTable,
            this.PriceComponentCodeName,
            this.PriceAttributeGroupTypeHeader,
            this.PriceAttributeGroupNameHeader);

        MarkupAutoTable::createOrUpdatePricingRuleForDataEntity(this, markupAutoTable, GUPPricingAttributeSourceLevel::Header, this.PriceAttributeGroupTypeHeader, this.PriceAttributeGroupNameHeader);
        MarkupAutoTable::createOrUpdatePricingRuleForDataEntity(this, markupAutoTable, GUPPricingAttributeSourceLevel::Line, GUPGroupAll::All, "");
    }

    if (_dataSourceCtx.name() == dataEntityDataSourceStr(GUPSalesAutomaticSalesDocumentHeaderChargeEntity, MarkupAutoLine))
    {
        MarkupAutoLine markupAutoLine = _dataSourceCtx.getBuffer() as MarkupAutoLine;
        MarkupAutoTable markupAutoTable = _entityCtx.getRuntimeContextByName(dataEntityDataSourceStr(GUPSalesAutomaticSalesDocumentHeaderChargeEntity, MarkupAutoTable)).getBuffer() as MarkupAutoTable;

        markupAutoLine.initFromAutoTable(markupAutoTable);
    }

    boolean ret = super(_entityCtx, _dataSourceCtx);

    return ret;
}

public boolean updateEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    if (_dataSourceCtx.name() == dataEntityDataSourceStr(GUPSalesAutomaticSalesDocumentHeaderChargeEntity, MarkupAutoTable))
    {
        MarkupAutoTable markupAutoTable = _dataSourceCtx.getBuffer() as markupAutoTable;

        this.updatePriceComponentCodeAndGroupCombination(
            markupAutoTable,
            this.PriceComponentCodeName,
            this.PriceAttributeGroupTypeHeader,
            this.PriceAttributeGroupNameHeader);

        MarkupAutoTable::createOrUpdatePricingRuleForDataEntity(this, markupAutoTable, GUPPricingAttributeSourceLevel::Header, this.PriceAttributeGroupTypeHeader, this.PriceAttributeGroupNameHeader);
        MarkupAutoTable::createOrUpdatePricingRuleForDataEntity(this, markupAutoTable, GUPPricingAttributeSourceLevel::Line, GUPGroupAll::All, "");
    }

    boolean ret = super(_entityCtx, _dataSourceCtx);

    return ret;
}

public void postLoad()
{
    super();

    if (this.PriceAttributeGroupTypeHeader == GUPGroupAll::Group && this.PricingRuleHeader)
    {
        this.setPriceAttributeValue(this.PricingRuleHeader, "Header");
    }
}

private void setPriceAttributeValue(RecId priceRuleId, str baseFieldName)
{
    GUPPricingRule rule;
    select firstonly crosscompany rule where rule.RecId == priceRuleId;

    if (rule.PriceAttributeGroupName)
    {
        int num = 1;
        GUPPricingRuleCondition ruleCondition;
        GUPPricingAttributeLink attributeLink;
        while select crosscompany ruleCondition
            where ruleCondition.RuleId == priceRuleId
            join attributeLink
            order by attributeLink.Priority asc
            where ruleCondition.ConditionAttribute == attributeLink.RecId
        {
            this.setFieldValue(baseFieldName + int2Str(num), ruleCondition.ConditionValue);
            num++;
        }
    }
}

private void updatePriceComponentCodeAndGroupCombination(
    MarkupAutoTable _markupAutoTable,
    GUPPriceComponentCodeName _codeName,
    GUPGroupAll _headerType,
    Name _headerGroupName)
{
    GUPPriceComponentCode componentCode;
    select firstonly componentCode
        where componentCode.PriceComponent == GUPPriceComponent::AutoCharges 
           && componentCode.Name == _codeName;

    if (!componentCode)
    {
        throw error(strfmt("@GlobalUnifiedPricing:GUPDataEntityInvalidRelationError", tablePName(GUPPriceComponentCode), _codeName));
    } 
    else if (_HeaderType == GUPGroupAll::All && !componentCode.HeaderPriceAttributeGroupAllEnabled)
    {
        throw error(strfmt("@GlobalUnifiedPricing:GUPPriceComponentCode_TypeAllNotEnabledErrorForHeader", _codeName));
    }

    GUPPriceComponentCodePriceAttributeGroupCombination groupCombination;
    select firstonly groupCombination
        where groupCombination.PriceComponentCodeName == _codeName
           && groupCombination.HeaderGroupAll == _headerType
           && groupCombination.LineGroupAll == GUPGroupAll::All
           && groupCombination.HeaderPriceAttributeGroupName == _headerGroupName
           && groupCombination.LinePriceAttributeGroupName == "";

    if (!groupCombination)
    {
        throw error(strfmt("@GlobalUnifiedPricing:GUPDataEntityInvalidRelationError", "Attribute group combination", _headerGroupName + "- All"));
    }

    _markupAutoTable.PriceAttributeGroupCombinationRecId = groupCombination.RecId;
}

private static str fixedChargeAmountDefinition()
{
    return GUPSalesAutomaticSalesDocumentHeaderChargeEntity::chargeCategoryValueDefinition(MarkupCategory::Fixed);
}

private static str chargePercentageDefinition()
{
    return GUPSalesAutomaticSalesDocumentHeaderChargeEntity::chargeCategoryValueDefinition(MarkupCategory::Percent);
}

private static str chargeCategoryValueDefinition(MarkupCategory _chargeCategory)
{
    return SysComputedColumn::codeDependentRelation(tableStr(GUPSalesAutomaticSalesDocumentHeaderChargeEntity),
                                                    dataEntityDataSourceStr(GUPSalesAutomaticSalesDocumentHeaderChargeEntity, MarkupAutoLine),
                                                    fieldStr(MarkupAutoLine, MarkupCategory),
                                                    _chargeCategory,
                                                    fieldStr(MarkupAutoLine, Value),
                                                    0.0);
}

